    assign is_one_hot = out;




    always @(*)
    begin
        case (in)
            10'b00_0000_0001: out = 1'b1;
            10'b00_0000_0010: out = 1'b1;
            10'b00_0000_0100: out = 1'b1;
            10'b00_0000_1000: out = 1'b1;
            10'b00_0001_0000: out = 1'b1;
