module top_module(

	input clk,
	input rst_n,


	output reg flag

);parameter MAX_NUM=25000_000;

reg [24:0] counter;







always @ (posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		flag <= 1'b0;
		counter <= 24'b0;
	end
	else if(counter < MAX_NUM - 1'b1) begin
		flag <= 1'b0;
		counter <= counter + 1'b1;
	end
	else begin
		flag <= 1'b1;
		counter <= 24'b0;
	end
end

endmodule

