description:
Design a glitch-free clock multiplexer that selects between multiple clock inputs based on a select signal. This module takes four clock signals as inputs and uses a synchronizer to ensure that the chosen clock signal is free from glitches during selection changes. It operates by first synchronizing the selected clock signal and then providing the final output, gclk, without undesired transitions. The design intent is to ensure reliable clock signal selection in digital circuits, minimizing the risk of timing issues that can arise from switching clock sources.
module top_module(
  input [n-1:0] clk,
  input sel,
  output gclk
);

code:
module top_module(
  input [n-1:0] clk,
  input sel,
  output gclk
);parameter n = 4; // number of input clock signals

reg [n-1:0] sync_clk;
reg [n-1:0] glitch_free_clk;

always @(posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3] or posedge sel) begin
  // Compare the input clock signals and select the one with the best timing characteristics
  case(sel)
    0: sync_clk <= clk[0];
    1: sync_clk <= clk[1];
    2: sync_clk <= clk[2];
    3: sync_clk <= clk[3];
    default: sync_clk <= clk[0];
  endcase
end

// Synchronizer circuit to remove any glitches from the selected clock signal
always @(posedge sync_clk[0] or posedge sync_clk[1] or posedge sync_clk[2] or posedge sync_clk[3]) begin
  case(sel)
    0: glitch_free_clk <= sync_clk[0];
    1: glitch_free_clk <= sync_clk[1];
    2: glitch_free_clk <= sync_clk[2];
    3: glitch_free_clk <= sync_clk[3];
    default: glitch_free_clk <= sync_clk[0];
  endcase
end

assign gclk = glitch_free_clk;

endmodule

module binary_to_gray(
    input       [3:0]   bin_in     ,

    output  reg [3:0]   gray_out
);

   always @(*) begin
       gray_out[3] = bin_in[3];
       gray_out[2] = bin_in[3] ^ bin_in[2];
       gray_out[1] = bin_in[2] ^ bin_in[1];
       gray_out[0] = bin_in[1] ^ bin_in[0];
   end

endmodule

