    input [3:0] data_in,
    input [1:0] control,
    output reg [3:0] data_out
);reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(posedge clk) begin
    stage1_out <= data_in;
end

always @(posedge clk) begin
    case (control)
        2'b00: stage2_out <= {stage1_out[2:0], 1'b0};
        2'b01: stage2_out <= {1'b0, stage1_out[3:1]};
        2'b10: stage2_out <= {stage1_out[0], stage1_out[3:1]};
        default: stage2_out <= stage1_out;
    endcase
end

always @(posedge clk) begin
    data_out <= stage2_out;
end

