description:
Design a circuit that functions as a controlled signal output. The output X follows the input A when the SLEEP signal is low (inactive). When SLEEP is high (active), the output X is driven low regardless of the value of A. This design can be useful in power management applications where the output needs to be disabled (set to low) during sleep modes.
module top_module(
    X    ,
    A    ,
    SLEEP
);

code:
module top_module(
    X    ,
    A    ,
    SLEEP
);output X    ;
    input  A    ;
    input  SLEEP;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = !SLEEP ? A : 1'b0;

endmodule

