module security_alarm (
	input clk,
	input resetn,
	input arm,
	output reg alarm);

	parameter DISARMED=0, ARMED=1, TRIGGERED=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= DISARMED;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			DISARMED: next_state = arm ? ARMED : DISARMED;
			ARMED: next_state = TRIGGERED;
			TRIGGERED: next_state = DISARMED;
			default: next_state = DISARMED;
		endcase
	end

	always @(state) begin
		case (state)
			TRIGGERED: alarm = 1;
			default: alarm = 0;
		endcase
	end
endmodule

