description:
Design a frequency divider circuit that generates a selectable clock signal based on the input `testmode`. The module has a 2-bit input `testmode` which selects one of four predefined division ratios, resulting in output signal `sigin1` toggling at different frequencies: 3125Hz, 250Hz, 50Hz, or 12500Hz. On each rising edge of the `sysclk` signal, the internal state is updated, and the output signal is inverted when the state reaches the predefined division value, allowing for precise control of the output frequency.
module top_module(
    input [1:0] testmode,
    input sysclk,
    output sigin1
);

code:
module top_module(
    input [1:0] testmode,
    input sysclk,
    output sigin1
);reg [20:0] state;
reg [20:0] divide;
reg sigin;

assign sigin1 = sigin;

initial
begin
    sigin = 0;
    state = 21'b000000000000000000000;
    divide = 21'b0_0000_0111_1101_0000_0000;
end

always @(testmode)
begin
    case(testmode[1:0])
    2'b00: divide = 21'b0_0000_0111_1101_0000_0000;  // 3125Hz, divide by 32000
    2'b01: divide = 21'b0_0000_0011_1110_1000_0000;  // 250Hz, divide by 400000
    2'b10: divide = 21'b1_1110_1000_0100_1000_0000;  // 50Hz, divide by 2000000
    2'b11: divide = 21'b0_0000_0001_1111_0100_0000;  // 12500Hz, divide by 8000
    endcase
end

always @(posedge sysclk)
begin
    if(state == 0)
        sigin = ~sigin;
    state = state + 21'd2;
    if(state == divide)
        state = 0;
end

endmodule

