module binary_counter_with_enable(
    input clk,
    input reset,
    input enable,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to zero
            q <= 4'b0000;
        end else if (enable) begin
            // Increment the counter by 1
            q <= q + 1;
        end
    end

endmodule

