module top_module(captureTrig0_d0,
    read_Mux_In,
    capturetrig0,
    s_axi_aclk);output captureTrig0_d0;
  input [0:0]read_Mux_In;
  input capturetrig0;
  input s_axi_aclk;

  wire CaptureTrig0_int;
  wire captureTrig0_d0;
  wire capturetrig0;
  wire [0:0]read_Mux_In;
  wire s_axi_aclk;
  wire s_level_out_d1_cdc_to;
  wire s_level_out_d2;
  wire s_level_out_d3;

  // Use the generic flip-flop definition as FDRE modules are not recognized
  reg s_level_out_d1_cdc_to_reg;
  reg s_level_out_d2_reg;
  reg s_level_out_d3_reg;
  reg CaptureTrig0_int_reg;

  always @(posedge s_axi_aclk) begin
    s_level_out_d1_cdc_to_reg <= capturetrig0; // Behaves like FDRE
    s_level_out_d2_reg <= s_level_out_d1_cdc_to_reg;
    s_level_out_d3_reg <= s_level_out_d2_reg;
    CaptureTrig0_int_reg <= s_level_out_d3_reg;
  end

  // Assign the internal registers to the wires
  assign s_level_out_d1_cdc_to = s_level_out_d1_cdc_to_reg;
  assign s_level_out_d2 = s_level_out_d2_reg;
  assign s_level_out_d3 = s_level_out_d3_reg;
  assign CaptureTrig0_int = CaptureTrig0_int_reg;

  // Use a generic 2-input LUT replacement
  assign captureTrig0_d0 = (read_Mux_In[0] == 1'b1) ? 1'b0 : CaptureTrig0_int;
endmodule

