module top_module(
    input a,
    input b,
    input c,
    input d,
    output reg out_func
);reg xor1_out, xor2_out;

always @(*) begin
    xor1_out = a ^ b;
end

always @(*) begin
    xor2_out = c ^ d;
end

always @(*) begin
    if (xor1_out == 0 && xor2_out == 0)
        out_func = 0;
    else if (xor1_out == 1 || xor2_out == 1)
        out_func = 1;
    else
        out_func = 0;
end

endmodule

module top_module(A, B, Y, R);parameter WIDTH = 1;

input [WIDTH-1:0] A, B;
output [WIDTH-1:0] Y, R;

wire [WIDTH*WIDTH-1:0] chaindata;
assign R = chaindata[WIDTH*WIDTH-1:WIDTH*(WIDTH-1)];

genvar i;
generate 
  for (i = 0; i < WIDTH; i=i+1) begin:stage
    wire [WIDTH-1:0] stage_in;

    if (i == 0) begin:cp
      assign stage_in = A;
    end else begin:cp
      assign stage_in = chaindata[i*WIDTH-1:(i-1)*WIDTH];
    end

    assign Y[WIDTH-(i+1)] = stage_in >= {B, {WIDTH-(i+1){1'b0}}};
    assign chaindata[(i+1)*WIDTH-1:i*WIDTH] = Y[WIDTH-(i+1)] ? stage_in - {B, {WIDTH-(i+1){1'b0}}} : stage_in;
  end
endgenerate

endmodule

module top_module(
	input               CC3200_SPI_CLK,
	input               CC3200_SPI_CS,
	output reg          CC3200_SPI_DIN,
	input               CC3200_SPI_DOUT,
	input               Envelop,
	output reg [7:0]    Line_Num, 
	output reg          Enable,
	output reg [1:0]    Zoom,
	output reg [5:0]    Gain,
	input  [7:0]        Trans_Data,
	output reg [8:0]    Trans_Addr

);reg [15:0] Config_Data_Shift;

    reg [3:0] SPI_Counter;

    reg [7:0] Shift_Data;




	always @(posedge CC3200_SPI_CLK or negedge CC3200_SPI_CS )
	begin
		if(~CC3200_SPI_CS) 
		    begin

			Line_Num  <= Config_Data_Shift[7:0];
			Zoom      <= Config_Data_Shift[15:14];
			Gain      <= Config_Data_Shift[13:8];
		 end
		else begin
			if(Trans_Addr == 9'd1 ) begin 
				Config_Data_Shift[15:8] <={Config_Data_Shift[14:8],CC3200_SPI_DOUT};
			end
			else if(Trans_Addr == 9'd2 ) begin 
				Config_Data_Shift[7:0] <={Config_Data_Shift[6:0],CC3200_SPI_DOUT} ;
			end
		end
	end





	always @(negedge CC3200_SPI_CLK or negedge CC3200_SPI_CS ) begin
		if(~CC3200_SPI_CS) begin
			SPI_Counter <= 8'd0;
			Shift_Data <=Trans_Data;	
		end
		else begin
			if(~Envelop) begin   
				SPI_Counter <= SPI_Counter + 1'b1;
				CC3200_SPI_DIN <= Shift_Data[7];
				Shift_Data <= Shift_Data <<1;
			end
		end
	end	


	always @(posedge CC3200_SPI_CS or posedge Envelop) begin       
		if(Envelop) begin
			Trans_Addr  <= 9'd0;
		end
		else begin
			Trans_Addr <= Trans_Addr + 1'b1;
		end
	end	




endmodule

module top_module(reset, clock, ps2c, ps2d, fifo_rd, fifo_data, fifo_empty,fifo_overflow, watchdog, count);input clock,reset,watchdog,ps2c,ps2d;
  input fifo_rd;
  output [7:0] fifo_data;
  output fifo_empty;
  output fifo_overflow;
  output [3:0] count;

  reg [3:0] count;      
  reg [9:0] shift;      

  reg [7:0] fifo[7:0];   
  reg fifo_overflow;
  reg [2:0] wptr,rptr;   

  wire [2:0] wptr_inc = wptr + 3'd1;

  assign fifo_empty = (wptr == rptr);
  assign fifo_data = fifo[rptr];


  reg [2:0] ps2c_sync;
  always @ (posedge clock) ps2c_sync <= {ps2c_sync[1:0],ps2c};
  wire sample = ps2c_sync[2] & ~ps2c_sync[1];

  reg timeout;
  always @(posedge clock) begin
    if(reset) begin
      count   <= 0;
      wptr    <= 0;
      rptr    <= 0;
      timeout <= 0;
      fifo_overflow <= 0;
    end else if (sample) begin

      if(count==10) begin

        if(shift[0]==0 && ps2d==1 && (^shift[9:1])==1) begin
          fifo[wptr] <= shift[8:1];
          wptr <= wptr_inc;
	  fifo_overflow <= fifo_overflow | (wptr_inc == rptr);
        end
        count <= 0;
        timeout <= 0;
      end else begin
        shift <= {ps2d,shift[9:1]};
        count <= count + 1;
      end
    end else if (watchdog && count!=0) begin
      if (timeout) begin

	count <= 0;
        timeout <= 0;
      end else timeout <= 1;
    end



    if (fifo_rd && !fifo_empty) begin
      rptr <= rptr + 1;
      fifo_overflow <= 0;
    end
  end

endmodule

