module top_module(
  input wire clk,
  input wire rst,
  input wire wr_en,
  input wire rd_en,
  input wire [7:0] din,
  output reg [7:0] dout,  // Changed from wire to reg
  output wire full,
  output wire empty
);localparam WIDTH = 8;
localparam AWIDTH = 4;
localparam DEPTH = 16;

reg [WIDTH-1:0] memory [DEPTH-1:0];
reg [AWIDTH-1:0] cnt_read;
reg [AWIDTH-1:0] cnt_write;

always @(posedge clk) begin
  if (rst) begin
    cnt_read <= 0;
    cnt_write <= 0;
    dout <= 0;  // Reset dout on reset
  end else begin
    if (wr_en && !full) begin
      memory[cnt_write] <= din;
      cnt_write <= cnt_write + 1;
    end
    if (rd_en && !empty) begin
      dout <= memory[cnt_read];
      cnt_read <= cnt_read + 1;
    end
  end
end

assign full = cnt_write == DEPTH;
assign empty = cnt_read == cnt_write;

endmodule

