  assign ENCLK = (EN) ? CLK : 1'b0; // Clock gating based on EN (simple implementation)

  always @(posedge ENCLK) begin
    if (EN && !TE) begin
      Q <= D;
    end
  end

  reg Q; // reg declaration needs to be at the top alongside other variable declarations

endmodule

