module top_module(
    input clk,
    input reset,          // Synchronous active-high reset
    input [9:0] d,        // 10-bit input for the shift register
    output [9:0] q,       // 10-bit output from the active module
    output reg [9:0] count_out // 10-bit output from the binary counter
);// Shift register using ring counter architecture
    reg [9:0] shift_reg [0:9]; // Fix the array size
    reg [3:0] shift_sel = 4'b0001;

    always @(posedge clk) begin
        if (reset) begin
            // Reset all shift register values individually
            shift_reg[0] <= 10'b0;
            shift_reg[1] <= 10'b0;
            shift_reg[2] <= 10'b0;
            shift_reg[3] <= 10'b0;
            shift_reg[4] <= 10'b0;
            shift_reg[5] <= 10'b0;
            shift_reg[6] <= 10'b0;
            shift_reg[7] <= 10'b0;
            shift_reg[8] <= 10'b0;
            shift_reg[9] <= 10'b0;
            shift_sel <= 4'b0001;
