module top_module (
	input clk,
	input [7:0] in,
	input reset,
	output match);parameter IDLE=0, S1=1, S2=2, S3=3, S4=4, S5=5, S6=6, S7=7, MATCH=8;
	reg [3:0] state;
	reg [3:0] next;

	always_comb begin
		case (state)
			IDLE: next = (in == 8'b10101010) ? MATCH : IDLE;
			MATCH: next = (in == 8'b10101010) ? MATCH : IDLE;
			default: next = IDLE;
		endcase
	end

	always @(posedge clk) begin
		if (reset) state <= IDLE;
		else state <= next;
	end

	assign match = (state == MATCH);

endmodule

